'use client';

import {
  AnimatePresence,
  LayoutGroup,
  motion,
  type Transition,
} from 'motion/react';
import { useRef, useState } from 'react';

import {
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { hold } from '@/registry/ndeko/lib/demonstration';
import { PlusIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Checkbox } from '@/registry/ndeko/ui/checkbox';
import { Input } from '@/registry/ndeko/ui/input';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

import { RollingCount } from './_parts/motion-parts';
import { actorNameOf, CURRENT_USER_ID, personOf } from './_parts/people';
import { PersonAvatar, StrikeTitle } from './_parts/subtask-parts';

type OpenGroup = 'prep' | 'launch';

type GroupId = OpenGroup | 'done';

type LiveItem = {
  id: string;
  title: string;
  group: OpenGroup;
  addedBy: string;
  isDone: boolean;
  doneBy?: string;
  doneOrder: number;
};

type Typing = {
  personId: string;
  group: OpenGroup;
};

const GROUPS: { id: GroupId; name: string; empty: string }[] = [
  { id: 'prep', name: 'Prep', empty: 'Nothing to prepare yet' },
  { id: 'launch', name: 'Launch', empty: 'Nothing planned for launch yet' },
  { id: 'done', name: 'Done', empty: 'Ticked items land here' },
];

const ADD_GROUPS: Segment<OpenGroup>[] = [
  { value: 'prep', label: 'Prep' },
  { value: 'launch', label: 'Launch' },
];

const MAX_ITEMS = 9;
const FRESH_FOR_MS = 1800;

const RESTING_ITEMS: LiveItem[] = [
  {
    id: 'prep-notes',
    title: 'Write the release notes',
    group: 'prep',
    addedBy: 'sana',
    isDone: false,
    doneOrder: 0,
  },
  {
    id: 'prep-pricing',
    title: 'Update the pricing page copy',
    group: 'prep',
    addedBy: 'leo',
    isDone: false,
    doneOrder: 0,
  },
  {
    id: 'launch-email',
    title: 'Schedule the announcement email',
    group: 'launch',
    addedBy: 'mei',
    isDone: false,
    doneOrder: 0,
  },
  {
    id: 'prep-freeze',
    title: 'Freeze the feature list',
    group: 'prep',
    addedBy: 'tomas',
    isDone: true,
    doneBy: 'tomas',
    doneOrder: 1,
  },
];

const TRAVEL: Transition = { type: 'spring', bounce: 0, duration: 0.35 };

const INSTANT: Transition = { duration: 0 };

function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return TRAVEL;
}

function layoutIdOf(id: string, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return undefined;
  }
  return `live-${id}`;
}

function arrivalOf(isFresh: boolean) {
  if (isFresh) {
    return { opacity: 0 };
  }
  return false;
}

function groupOf(item: LiveItem): GroupId {
  if (item.isDone) {
    return 'done';
  }
  return item.group;
}

function itemsInGroup(items: LiveItem[], group: GroupId) {
  const inGroup = items.filter((item) => groupOf(item) === group);
  if (group !== 'done') {
    return inGroup;
  }
  return [...inGroup].sort(
    (first, second) => second.doneOrder - first.doneOrder
  );
}

function signatureOf(items: LiveItem[]) {
  return items.map((item) => `${item.id}:${groupOf(item)}`).join('|');
}

function metaPersonIdOf(item: LiveItem) {
  if (item.isDone && item.doneBy) {
    return item.doneBy;
  }
  return item.addedBy;
}

function metaLabelOf(item: LiveItem) {
  const name = actorNameOf(metaPersonIdOf(item));
  if (item.isDone) {
    return `Ticked by ${name}`;
  }
  return `Added by ${name}`;
}

function shortNameOf(personId: string) {
  if (personId === CURRENT_USER_ID) {
    return 'You';
  }
  return personOf(personId).firstName;
}

function withoutOldest(items: LiveItem[]) {
  const oldestDone = items.find((item) => item.isDone);
  const dropped = oldestDone ?? items[0];
  return items.filter((item) => item.id !== dropped.id);
}

function withCap(items: LiveItem[]) {
  if (items.length <= MAX_ITEMS) {
    return items;
  }
  return withoutOldest(items);
}

function groupNameOf(group: OpenGroup) {
  if (group === 'launch') {
    return 'Launch';
  }
  return 'Prep';
}

type LiveRowProps = {
  item: LiveItem;
  isFresh: boolean;
  signature: string;
  onToggle: () => void;
};

function LiveRow({ item, isFresh, signature, onToggle }: LiveRowProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const metaId = metaPersonIdOf(item);

  return (
    <motion.li
      layout='position'
      layoutId={layoutIdOf(item.id, shouldReduceMotion)}
      layoutDependency={signature}
      initial={arrivalOf(isFresh)}
      animate={{ opacity: 1 }}
      transition={travelOf(shouldReduceMotion)}
      data-fresh={isFresh}
      className='group/row'
    >
      <label className='hover:bg-foreground/[0.03] group-data-[fresh=true]/row:bg-primary/10 flex h-9 cursor-pointer items-center gap-3 rounded-lg px-3 transition-colors duration-1000'>
        <Checkbox checked={item.isDone} onCheckedChange={onToggle} />
        <StrikeTitle title={item.title} isDone={item.isDone} />
        <span
          aria-label={metaLabelOf(item)}
          className='text-muted-foreground ms-auto flex shrink-0 items-center gap-1.5 text-xs'
        >
          <PersonAvatar person={personOf(metaId)} />
          <span className='hidden max-w-16 truncate @xs:inline'>
            {shortNameOf(metaId)}
          </span>
        </span>
      </label>
    </motion.li>
  );
}

type GroupProps = {
  name: string;
  empty: string;
  items: LiveItem[];
  freshId: string | null;
  signature: string;
  onToggle: (id: string) => void;
};

function Group({
  name,
  empty,
  items,
  freshId,
  signature,
  onToggle,
}: GroupProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const hasItems = items.length > 0;

  return (
    <section aria-label={name} className='flex flex-col'>
      <motion.div
        layout='position'
        layoutDependency={signature}
        transition={travelOf(shouldReduceMotion)}
        className='flex h-7 items-center justify-between px-3'
      >
        <h3 className='text-muted-foreground text-xs font-medium'>{name}</h3>
        <span className='text-muted-foreground text-xs'>
          <RollingCount value={items.length} />
        </span>
      </motion.div>
      <ul>
        {items.map((item) => (
          <LiveRow
            key={item.id}
            item={item}
            isFresh={item.id === freshId}
            signature={signature}
            onToggle={() => onToggle(item.id)}
          />
        ))}
      </ul>
      {!hasItems && (
        <p className='text-muted-foreground px-3 py-2 text-[13px]'>{empty}</p>
      )}
    </section>
  );
}

function enterScaleOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 1;
  }
  return 0.96;
}

function TypingStrip({ typing }: { typing: Typing | null }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const enter = { opacity: 0, y: 4, scale: enterScaleOf(shouldReduceMotion) };

  return (
    <div className='flex h-6 items-center px-3'>
      <AnimatePresence mode='popLayout' initial={false}>
        {typing && (
          <motion.span
            key={typing.personId}
            initial={enter}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, transition: { duration: 0.1 } }}
            transition={{ duration: 0.18, ease: [0.23, 1, 0.32, 1] }}
            className='text-muted-foreground flex items-center gap-1.5 text-xs'
          >
            <PersonAvatar person={personOf(typing.personId)} />
            {shortNameOf(typing.personId)} is adding to{' '}
            {groupNameOf(typing.group)}
          </motion.span>
        )}
      </AnimatePresence>
    </div>
  );
}

export default function Subtask08() {
  const [items, setItems] = useState(RESTING_ITEMS);
  const [typing, setTyping] = useState<Typing | null>(null);
  const [freshId, setFreshId] = useState<string | null>(null);
  const [draft, setDraft] = useState('');
  const [addGroup, setAddGroup] = useState<OpenGroup>('prep');
  const [announcement, setAnnouncement] = useState('');
  const counter = useRef({ items: 0, ticks: 1 });
  const { schedule, clearAll } = useTimeouts();
  const signature = signatureOf(items);
  const doneCount = items.filter((item) => item.isDone).length;

  function addItem(title: string, group: OpenGroup, personId: string) {
    counter.current.items += 1;
    const id = `live-${counter.current.items}`;
    const item: LiveItem = {
      id,
      title,
      group,
      addedBy: personId,
      isDone: false,
      doneOrder: 0,
    };
    setItems((current) => withCap([...current, item]));
    setTyping(null);
    setFreshId(id);
    schedule(() => setFreshId(null), FRESH_FOR_MS);
  }

  function setTicked(id: string, personId: string) {
    counter.current.ticks += 1;
    const order = counter.current.ticks;
    setItems((current) =>
      current.map((item) => {
        if (item.id !== id) {
          return item;
        }
        if (item.isDone) {
          return { ...item, isDone: false, doneBy: undefined, doneOrder: 0 };
        }
        return { ...item, isDone: true, doneBy: personId, doneOrder: order };
      })
    );
  }

  function toggleFromPerson(id: string) {
    const item = items.find((candidate) => candidate.id === id);
    setTicked(id, CURRENT_USER_ID);
    if (!item) {
      return;
    }
    if (item.isDone) {
      setAnnouncement(`${item.title} is open again`);
      return;
    }
    setAnnouncement(`${item.title} moved to Done`);
  }

  function submitDraft(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const title = draft.trim();
    if (title === '') {
      return;
    }
    addItem(title, addGroup, CURRENT_USER_ID);
    setDraft('');
    setAnnouncement(`${title} added to ${groupNameOf(addGroup)}`);
  }

  function startOver() {
    clearAll();
    setItems(RESTING_ITEMS);
    setTyping(null);
    setFreshId(null);
  }

  const steps: AutoplayStep[] = [
    { after: 2200, run: () => setTyping({ personId: 'leo', group: 'launch' }) },
    {
      after: 1100,
      run: () => addItem('Confirm the status page text', 'launch', 'leo'),
    },
    { after: 1800, run: () => setTicked('prep-notes', 'sana') },
    { after: 1600, run: () => setTyping({ personId: 'mei', group: 'prep' }) },
    {
      after: 1000,
      run: () => addItem('Book the launch call', 'prep', 'mei'),
    },
    { after: 1800, run: () => setTicked('launch-email', 'tomas') },
    { after: 1800, run: () => setTicked('prep-pricing', 'sana') },
    { after: 1600, run: hold },
  ];
  const { ref } = useAutoplay(steps, {
    loopAfter: 2600,
    onReset: startOver,
  });

  useKeptHeight(ref);

  return (
    <div
      ref={ref}
      className='bg-foreground/[0.025] @container flex h-[27rem] w-full max-w-md flex-col rounded-xl p-1'
    >
      <div className='flex items-baseline justify-between gap-2 px-3 pt-2 pb-1'>
        <h3 className='text-sm font-medium'>Launch checklist</h3>
        <span className='text-muted-foreground text-xs'>
          <RollingCount value={doneCount} /> of {items.length} done
        </span>
      </div>
      <LayoutGroup>
        <div className='min-h-0 flex-1 overflow-y-auto'>
          {GROUPS.map((group) => (
            <Group
              key={group.id}
              name={group.name}
              empty={group.empty}
              items={itemsInGroup(items, group.id)}
              freshId={freshId}
              signature={signature}
              onToggle={toggleFromPerson}
            />
          ))}
        </div>
      </LayoutGroup>
      <TypingStrip typing={typing} />
      <form
        onSubmit={submitDraft}
        className='flex flex-wrap items-center gap-2 px-2 pt-1 pb-2'
      >
        <Input
          aria-label='New item'
          placeholder={`Add to ${groupNameOf(addGroup)}`}
          value={draft}
          onChange={(event) => setDraft(event.currentTarget.value)}
          className='min-w-40 flex-1'
        />
        <Segments
          label='Group'
          value={addGroup}
          segments={ADD_GROUPS}
          onValueChange={setAddGroup}
        />
        <Button
          type='submit'
          size='icon'
          aria-label='Add item'
          disabled={draft.trim() === ''}
          className='shrink-0'
        >
          <PlusIcon />
        </Button>
      </form>
      <LiveRegion message={announcement} />
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

export const EASE_OUT_STRONG: [number, number, number, number] = [
  0.23, 1, 0.32, 1,
];

export const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

export const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

export type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

/** Rows that arrive or leave a list: their height opens and closes so the rows after them slide. */
export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

/** An icon or a short label that becomes another one in place. */
export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={swapVariantsOf(shouldReduceMotion)}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const COUNT_SLIDE = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const COUNT_VARIANTS: Variants = {
  enter: (offset: number) => ({ y: offset, opacity: 0 }),
  center: { y: 0, opacity: 1 },
  leave: (offset: number) => ({ y: -offset, opacity: 0 }),
};

function directionOf(previous: number, next: number) {
  if (next < previous) {
    return -1;
  }
  return 1;
}

function offsetOf(direction: number, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 0;
  }
  return direction * COUNT_SLIDE;
}

type RollingCountProps = {
  value: number;
  /** Writes the value, such as a duration; the digits still roll on the number. */
  format?: (value: number) => string;
  className?: string;
};

function plainNumber(value: number) {
  return String(value);
}

/** A figure the person just changed: the new digits slide in from the side of the change. */
export function RollingCount({
  value,
  format = plainNumber,
  className,
}: RollingCountProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const [previous, setPrevious] = useState(value);
  const [direction, setDirection] = useState(1);

  if (previous !== value) {
    setDirection(directionOf(previous, value));
    setPrevious(value);
  }

  const offset = offsetOf(direction, shouldReduceMotion);

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false} custom={offset}>
        <motion.span
          key={value}
          custom={offset}
          variants={COUNT_VARIANTS}
          initial='enter'
          animate='center'
          exit='leave'
          transition={COUNT_TRANSITION}
          className='inline-block'
        >
          {format(value)}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export type Person = {
  id: string;
  name: string;
  firstName: string;
};

export const CURRENT_USER_ID = 'amara';

export const PEOPLE: Person[] = [
  {
    id: 'amara',
    name: 'Amara Okafor',
    firstName: 'Amara',
  },
  {
    id: 'leo',
    name: 'Léo Martin',
    firstName: 'Léo',
  },
  {
    id: 'sana',
    name: 'Sana Iqbal',
    firstName: 'Sana',
  },
  {
    id: 'tomas',
    name: 'Tomás Rivera',
    firstName: 'Tomás',
  },
  {
    id: 'mei',
    name: 'Mei Lin',
    firstName: 'Mei',
  },
  {
    id: 'jonah',
    name: 'Jonah Brandt',
    firstName: 'Jonah',
  },
];

export function personOf(id: string) {
  const found = PEOPLE.find((person) => person.id === id);
  if (found) {
    return found;
  }
  return PEOPLE[0];
}

export function isCurrentUser(id: string) {
  return id === CURRENT_USER_ID;
}

export function actorNameOf(id: string) {
  if (isCurrentUser(id)) {
    return 'You';
  }
  return personOf(id).name;
}

'use client';

import { CheckIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';

import { Swap } from './motion-parts';
import type { Person } from './people';

export type StatusId =
  'backlog' | 'todo' | 'in_progress' | 'in_review' | 'done';

export const STATUSES: { id: StatusId; name: string; color: string }[] = [
  { id: 'backlog', name: 'Backlog', color: 'var(--muted-foreground)' },
  { id: 'todo', name: 'Todo', color: 'var(--muted-foreground)' },
  { id: 'in_progress', name: 'In progress', color: 'var(--warning)' },
  { id: 'in_review', name: 'In review', color: 'var(--primary)' },
  { id: 'done', name: 'Done', color: 'var(--success)' },
];

export function statusOf(id: StatusId) {
  const found = STATUSES.find((status) => status.id === id);
  if (found) {
    return found;
  }
  return STATUSES[0];
}

export function isStatusId(value: unknown): value is StatusId {
  return STATUSES.some((status) => status.id === value);
}

const PIE_RADIUS = 2;

const PIE_CIRCUMFERENCE = 2 * Math.PI * PIE_RADIUS;

function StartedShape({ share }: { share: number }) {
  const filled = share * PIE_CIRCUMFERENCE;
  return (
    <>
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
      <circle
        cx='7'
        cy='7'
        r={PIE_RADIUS}
        stroke='currentColor'
        strokeWidth={PIE_RADIUS * 2}
        strokeDasharray={`${filled} ${PIE_CIRCUMFERENCE}`}
        transform='rotate(-90 7 7)'
      />
    </>
  );
}

function statusShapeOf(status: StatusId) {
  if (status === 'backlog') {
    return (
      <circle
        cx='7'
        cy='7'
        r='6'
        stroke='currentColor'
        strokeWidth='1.5'
        strokeDasharray='1.6 1.9'
      />
    );
  }
  if (status === 'todo') {
    return (
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
    );
  }
  if (status === 'in_progress') {
    return <StartedShape share={0.5} />;
  }
  if (status === 'in_review') {
    return <StartedShape share={0.75} />;
  }
  return (
    <>
      <circle cx='7' cy='7' r='7' fill='currentColor' />
      <path
        d='M4.4 7.2 6.2 9l3.4-3.8'
        stroke='var(--card)'
        strokeWidth='1.6'
        strokeLinecap='round'
        strokeLinejoin='round'
      />
    </>
  );
}

export function StatusGlyph({
  status,
  className,
}: {
  status: StatusId;
  className?: string;
}) {
  const glyphStyle = { color: statusOf(status).color } as React.CSSProperties;
  return (
    <svg
      viewBox='0 0 14 14'
      fill='none'
      aria-hidden='true'
      style={glyphStyle}
      className={cn('size-3.5 shrink-0', className)}
    >
      {statusShapeOf(status)}
    </svg>
  );
}

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={cn('size-5 text-[9px]', className)} seed={person.name} />
  );
}

const RING_RADIUS = 6.5;

const RING_LENGTH = 2 * Math.PI * RING_RADIUS;

function shareOf(done: number, total: number) {
  if (total === 0) {
    return 0;
  }
  return done / total;
}

function ringKeyOf(isComplete: boolean) {
  if (isComplete) {
    return 'complete';
  }
  return 'ring';
}

/** The share of sub-tasks done; the arc travels on each check and becomes a check mark once all are done. */
export function ProgressRing({
  done,
  total,
  className,
}: {
  done: number;
  total: number;
  className?: string;
}) {
  const share = shareOf(done, total);
  const isComplete = total > 0 && done === total;
  const dashOffset = RING_LENGTH * (1 - share);

  return (
    <Swap swapKey={ringKeyOf(isComplete)} className={className}>
      {isComplete && (
        <span className='bg-success/15 text-success-foreground flex size-4 items-center justify-center rounded-full'>
          <CheckIcon strokeWidth={3} className='size-2.5' />
        </span>
      )}
      {!isComplete && (
        <svg
          viewBox='0 0 16 16'
          aria-hidden='true'
          className='size-4 -rotate-90'
        >
          <circle
            cx='8'
            cy='8'
            r={RING_RADIUS}
            fill='none'
            strokeWidth='2'
            className='stroke-foreground/10'
          />
          <circle
            cx='8'
            cy='8'
            r={RING_RADIUS}
            fill='none'
            strokeWidth='2'
            strokeLinecap='round'
            strokeDasharray={RING_LENGTH}
            strokeDashoffset={dashOffset}
            className='stroke-primary transition-[stroke-dashoffset] duration-300 ease-(--ease-out-strong)'
          />
        </svg>
      )}
    </Swap>
  );
}

/** A title that gets struck through from left to right when its sub-task is done. */
export function StrikeTitle({
  title,
  isDone,
  className,
}: {
  title: string;
  isDone: boolean;
  className?: string;
}) {
  return (
    <span
      className={cn(
        'relative min-w-0 truncate text-[13px] transition-colors duration-200',
        isDone && 'text-muted-foreground',
        className
      )}
    >
      {title}
      <span
        aria-hidden='true'
        className={cn(
          'bg-foreground/35 pointer-events-none absolute inset-x-0 top-1/2 h-px origin-left scale-x-0 transition-transform duration-200 ease-(--ease-out-strong)',
          isDone && 'scale-x-100'
        )}
      />
    </span>
  );
}

/** One segment per sub-task, filled from the left when it is done. */
export function SegmentMeter({
  states,
  className,
}: {
  states: boolean[];
  className?: string;
}) {
  return (
    <span aria-hidden='true' className={cn('flex gap-0.5', className)}>
      {states.map((isDone, index) => (
        <span
          key={index}
          className='bg-foreground/10 relative h-1.5 min-w-1 flex-1 overflow-hidden rounded-full'
        >
          <span
            className={cn(
              'bg-success absolute inset-0 origin-left scale-x-0 rounded-full transition-transform duration-200 ease-(--ease-out-strong)',
              isDone && 'scale-x-100'
            )}
          />
        </span>
      ))}
    </span>
  );
}
